def compute(data):
    daily = data["daily"]
    max_range = -1
    max_date = None
    for day in daily:
        diff = day["tempMax"] - day["tempMin"]
        if diff > max_range:
            max_range = diff
            max_date = day["date"]
    return {"date": max_date, "range": round(max_range, 1)}

