def compute(data):
    monthly = data["monthly"]
    # 找到今年6月和去年6月的降水数据
    precip_by_year = {}
    for record in monthly:
        if record["month"] == 6:
            precip_by_year[record["year"]] = record["totalPrecip"]
    years = sorted(precip_by_year.keys())
    this_year = years[-1]
    last_year = years[-2]
    diff = precip_by_year[this_year] - precip_by_year[last_year]
    return round(diff, 1)

